// lib/star/tuningStore.ts
var SCALAR_KEY = "star-tuning-v1";
var PRICE_KEY = "star-tuning-prices-v1";
function hasLocalStorage() {
  return typeof localStorage !== "undefined";
}
function readJson(key, fallback) {
  if (!hasLocalStorage()) return fallback;
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : fallback;
  } catch {
    return fallback;
  }
}
var DEFAULTS = new Map(TUNABLES.map((t) => [t.key, t.default]));
function getTuning(key) {
  const fallback = DEFAULTS.get(key);
  if (fallback === void 0) {
    if (process.env.NODE_ENV !== "production") {
      console.error(`getTuning: no registry entry for "${key}"`);
    }
    return 0;
  }
  const v3 = readJson(SCALAR_KEY, {})[key];
  return typeof v3 === "number" && Number.isFinite(v3) ? v3 : fallback;
}
function getCataloguePriceOverrides(catalogue) {
  return readJson(PRICE_KEY, {})[catalogue] ?? {};
}
function applyPriceOverrides(catalogue, rows) {
  const overrides = getCataloguePriceOverrides(catalogue);
  if (Object.keys(overrides).length === 0) return [...rows];
  return rows.map((row) => {
    const fields = overrides[row.id];
    if (!fields) return row;
    return { ...row, ...fields };
  });
}

