var DIVISION_BY_CLUB = new Map([
  ...PREMIER_LEAGUE_CLUBS.map((c) => [c, "premier"]),
  ...CHAMPIONSHIP_CLUBS.map((c) => [c, "championship"]),
  ...PROMOTION_POOL_CLUBS.map((c) => [c, "pool"]),
  ...OTHER_CLUBS.map((c) => [c, "pool"]),
  ...CHAMPIONS_LEAGUE_CLUBS.map((c) => [c, "champions"]),
  ...EUROPA_LEAGUE_CLUBS.map((c) => [c, "europa"]),
  // Spread after PROMOTION_POOL_CLUBS on purpose — five of these clubs are
  // also in that list (see its own note above); this tag wins for them,
  // same "last spread wins" pattern the Champions/Europa lists already rely
  // on for a club like Arsenal.
  ...LEAGUE_ONE_CLUBS.map((c) => [c, "league_one"]),
  ...LEAGUE_TWO_CLUBS.map((c) => [c, "league_two"]),
  ...NATIONAL_LEAGUE_CLUBS.map((c) => [c, "national_league"]),
  ...NATIONAL_LEAGUE_NORTH_CLUBS.map((c) => [c, "national_league_north"]),
  ...NATIONAL_LEAGUE_SOUTH_CLUBS.map((c) => [c, "national_league_south"]),
  ...STEP3_NORTH_CLUBS.map((c) => [c, "step3_north"]),
  ...STEP3_SOUTH_CLUBS.map((c) => [c, "step3_south"])
]);
function divisionOf(club2) {
  return DIVISION_BY_CLUB.get(club2) ?? null;
}
function externalClubsFor(domesticClubs) {
  const domestic = new Set(domesticClubs);
  const world = /* @__PURE__ */ new Set([
    ...CHAMPIONS_LEAGUE_CLUBS,
    ...EUROPA_LEAGUE_CLUBS,
    ...OTHER_CLUBS,
    ...PROMOTION_POOL_CLUBS,
    ...PREMIER_LEAGUE_CLUBS,
    ...CHAMPIONSHIP_CLUBS,
    // The FA Cup's Round of 64 (cups.ts's faCupField) now genuinely draws
    // from League One, League Two, AND the National League — not just the
    // tier immediately below, the way the League Cup's belowField still
    // does. All three need their squads fetchable here too, or an FA Cup
    // opponent from League Two/the National League hits the exact
    // "Unable to scout opponent's team" bug this list's own history
    // already records for a Championship club once.
    ...LEAGUE_ONE_CLUBS,
    ...LEAGUE_TWO_CLUBS,
    ...NATIONAL_LEAGUE_CLUBS
  ]);
  return Array.from(world).filter((c) => !domestic.has(c));
}

// lib/star/squadSaveCodec.ts
var fetched = /* @__PURE__ */ new Map();
function rememberFetchedSquads(squads) {
  for (const s of squads) for (const p of s.players) fetched.set(p.id, p);
}

