function checkNewAchievements(career) {
  const unlocked = [];
  for (const a of ACHIEVEMENTS) {
    if (career.achievements.includes(a.id)) continue;
    let ok2 = false;
    try {
      ok2 = a.check(career);
    } catch {
      ok2 = false;
    }
    if (ok2) unlocked.push(a.id);
  }
  return unlocked;
}

