// lib/star/euroBracket.ts
var EURO_KO_ROUNDS = ["Round of 32", "Round of 16", "Quarter-Final", "Semi-Final", "Final"];
function openEuroBracket(table3, rng) {
  const pos = (n3) => table3[n3 - 1];
  const finish = {};
  table3.slice(0, 24).forEach((c, i) => {
    finish[c] = i + 1;
  });
  const swap = (p) => rng() < 0.5 ? p : [p[1], p[0]];
  const seedPairFor = [[7, 8], [5, 6], [3, 4], [1, 2]];
  const band = (k2) => {
    const [u0, u1] = swap([23 - 2 * k2, 24 - 2 * k2]);
    const ties = [[9 + 2 * k2, u0], [10 + 2 * k2, u1]];
    const seeds2 = swap([seedPairFor[k2][0], seedPairFor[k2][1]]);
    return { ties: swap(ties), seeds: seeds2 };
  };
  const b = [0, 1, 2, 3].map(band);
  const order = [3, 0, 2, 1];
  const seeds = [];
  const playOff = [];
  for (const half of [0, 1]) {
    for (const k2 of order) {
      seeds.push(pos(b[k2].seeds[half]));
      const [hi, lo] = b[k2].ties[half];
      playOff.push({ a: pos(hi), b: pos(lo), legs: [] });
    }
  }
  const empty = (n3) => Array.from({ length: n3 }, () => ({ legs: [] }));
  return {
    finish,
    seeds,
    rounds: [
      { name: EURO_KO_ROUNDS[0], ties: playOff },
      { name: EURO_KO_ROUNDS[1], ties: seeds.map((s) => ({ a: s, legs: [] })) },
      { name: EURO_KO_ROUNDS[2], ties: empty(4) },
      { name: EURO_KO_ROUNDS[3], ties: empty(2) },
      { name: EURO_KO_ROUNDS[4], ties: empty(1) }
    ]
  };
}
function playTie(t, single2, str2, sim, rng) {
  const sa = str2(t.a), sb = str2(t.b);
  const legs = [];
  if (single2) {
    const [x, y] = sim(sa, sb, rng);
    legs.push({ a: x, b: y, aHome: true });
  } else {
    const [h1, a1] = sim(sb, sa, rng);
    legs.push({ a: a1, b: h1, aHome: false });
    const [h2, a2] = sim(sa, sb, rng);
    legs.push({ a: h2, b: a2, aHome: true });
  }
  let ta = legs.reduce((s, l) => s + l.a, 0);
  let tb = legs.reduce((s, l) => s + l.b, 0);
  const out = { ...t, legs };
  if (ta === tb) {
    const et = extraTimeScore(sa, sb, rng);
    out.et = { a: et.hs, b: et.as };
    const last = legs[legs.length - 1];
    legs[legs.length - 1] = { ...last, a: last.a + et.hs, b: last.b + et.as };
    ta += et.hs;
    tb += et.as;
    if (ta === tb) {
      const p = simulateShootout(sa, sb, rng);
      out.pens = { a: p.home, b: p.away };
    }
  }
  out.winner = ta !== tb ? ta > tb ? t.a : t.b : out.pens.a > out.pens.b ? t.a : t.b;
  return out;
}
function ordered(br, x, y) {
  const fx = br.finish[x] ?? 99, fy = br.finish[y] ?? 99;
  return fx <= fy ? [x, y] : [y, x];
}
function advanceEuroBracket(br, you5, str2, sim, rng, upToRound = Infinity) {
  const rounds = br.rounds.map((r) => ({ ...r, ties: r.ties.map((t) => ({ ...t, legs: [...t.legs] })) }));
  let winner = br.winner;
  for (let guard = 0; guard < 12; guard++) {
    let changed = false;
    rounds.forEach((r, ri) => {
      r.ties.forEach((t, ti) => {
        if (ri <= upToRound && t.a && t.b && !t.winner && t.a !== you5 && t.b !== you5) {
          r.ties[ti] = playTie(t, r.name === "Final", str2, sim, rng);
          changed = true;
        }
      });
      const next = rounds[ri + 1];
      if (!next) return;
      next.ties.forEach((nt, j) => {
        if (nt.a && nt.b) return;
        if (ri === 0) {
          const w = r.ties[j]?.winner;
          if (w && nt.a) {
            const [x, y] = ordered(br, nt.a, w);
            next.ties[j] = { ...nt, a: x, b: y };
            changed = true;
          }
          return;
        }
        const w1 = r.ties[2 * j]?.winner, w2 = r.ties[2 * j + 1]?.winner;
        if (w1 && w2) {
          const [x, y] = ordered(br, w1, w2);
          next.ties[j] = { ...nt, a: x, b: y };
          changed = true;
        }
      });
    });
    const fin = rounds[rounds.length - 1].ties[0];
    if (fin.winner && fin.winner !== winner) {
      winner = fin.winner;
      changed = true;
    }
    if (!changed) break;
  }
  return { ...br, rounds, winner };
}
function yourKoTie(br, you5) {
  for (const r of br.rounds) {
    const t = r.ties.find((x) => !x.winner && x.a && x.b && (x.a === you5 || x.b === you5));
    if (t) return { round: r.name, tie: t };
  }
  return null;
}
