function chooseAngle(event, account2, memory, cycleId) {
  const rng = rngFor3("angle", cycleId, event.id, account2.id);
  const negative = event.tags.some((t) => NEGATIVE_TAGS.has(t));
  const hostile = account2.allegiance?.polarity === -1;
  const sentiment = hostile ? negative ? 1 : -1 : negative ? -1 : event.tags.includes("goal") || event.tags.includes("trophy") ? 1 : 0;
  let frames = FRAMES[account2.archetype];
  if (!hostile && negative) frames = frames.filter((f2) => f2 !== "celebrate");
  if (!frames.length) frames = ["report"];
  const frame = pick4(frames, rng);
  const prefs = LEAD_PREFERENCE[account2.archetype] ?? ["score"];
  const lead = prefs.find((k2) => event.facts[k2] !== void 0 && event.facts[k2] !== "") ?? "score";
  const secondary = prefs.find((k2) => k2 !== lead && event.facts[k2] !== void 0 && event.facts[k2] !== "");
  const threadish = ["stats", "broadsheet", "pundit", "tabloid", "league"];
  const useThread = !!event.thread && event.thread.heat >= 45 && Number(event.thread.facts.matches ?? 0) >= 2 && threadish.includes(account2.archetype) && rng() < 0.8;
  return { lead, secondary, sentiment, frame, useThread };
}

